import{_ as o,l as i,o as a,c as s,v as t,p as l,x as n,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"流水线异常","description":"","frontmatter":{"title":"流水线异常","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pipeline-exception.md","filePath":"cs/pipeline-exception.md","lastUpdated":1789023840000}'),B={name:"cs/pipeline-exception.md"};function c(h,e,C,_,P,m){const r=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="流水线异常" tabindex="-1">流水线异常 <a class="header-anchor" href="#流水线异常" aria-label="Permalink to &quot;流水线异常&quot;">​</a></h1><div class="epigraph"><p>流水线里同时活着好几条指令时，异常仍必须看起来像发生在某条指令的边界上。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/tournament-predict">上一课</a>让 IF 按预测取指，错了就冲刷。<a href="/cs/exception-interrupt-entry">异常与中断入口</a>和<a href="/cs/privilege-rings">特权级</a>已经规定：陷入时保存 PC、切到更高特权、跳到入口。本课不重讲入口约定。缺口是：五级里 IF 可能缺页、EX 可能溢出、MEM 可能缺页，几件事可以挤在同一拍。本课只要求<strong>精确异常</strong>：提交点之前的指令全部完成，之后的当作没发生。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单周期里异常与当前指令同一拍，PC 就是那条指令。流水线里，MEM 的 load 缺页时，后面的 IF/ID 已经取了不该留下的指令，前面的 add 可能刚要写回。若让 IF 的对齐错优先于更早指令的缺页，软件看见的 EPC 会跳。缺口不是新的陷阱类型，而是<strong>按程序序仲裁，并在提交前冲刷年轻指令</strong>。</p><p>中断是异步的，通常挂到某条指令的提交边界，而不是卡在组合逻辑中间。本课把中断与同步异常放在同一套提交纪律下。</p><p><span class="marginnote">不精确异常曾出现在早期流水线浮点核：EPC 不能指出哪一条。操作系统和调试几乎无法接受。教学整数核必须精确。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>指定 WB 前或 MEM 结束为提交点：只有到达该点的指令可以改架构状态（寄存器堆、已提交的存储）。更年轻的级一律冲刷。同一拍多处异常，选最年长的那条指令对应的原因，把 EPC 写成它的 PC。</p>',9)),(a(),l(E,null,{default:n(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E5%B9%B4%E9%95%BF%E6%8C%87%E4%BB%A4%E5%BC%82%E5%B8%B8%22%5D%20--%3E%20PICK%5B%22%E6%8C%89%E7%A8%8B%E5%BA%8F%E5%BA%8F%E9%80%89%E4%B8%80%E6%9D%A1%22%5D%0A%20%20YOUNG%5B%22%E5%B9%B4%E8%BD%BB%E6%8C%87%E4%BB%A4%E5%BC%82%E5%B8%B8%22%5D%20--%3E%20PICK%0A%20%20PICK%20--%3E%20FLUSH%5B%22%E5%86%B2%E5%88%B7%E5%B9%B4%E8%BD%BB%E7%BA%A7%22%5D%0A%20%20PICK%20--%3E%20TRAP%5B%22%E5%86%99%20EPC%EF%BC%8C%E5%88%87%E7%89%B9%E6%9D%83%EF%BC%8C%E8%B7%B3%E5%85%A5%E5%8F%A3%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>load 缺页时，该 load 本身未提交，重试时从它再取。这与误预测冲刷相同：流水线寄存器作废；不同的是接下来进入陷阱处理，而不是用户目标地址。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>精确性把「流水线内部的重叠」对软件藏起来。处理程序看见的寄存器堆，等于异常指令之前所有指令都已顺序执行完毕。转发与预测仍然存在，但它们改的是未提交状态；提交点一到，旁路值必须已经写入或被丢弃。</p><p>外部中断可以等当前指令提交再进陷阱，避免在 ALU 中间切开。缺页、非法指令不能推迟到后面的指令提交之后，否则软件会看见不该存在的写回。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入重排序缓冲：五级顺序流水线用固定提交点就够。<a href="/cs/ooo-rob">乱序与 ROB</a> 才在乱序执行时用 ROB 重建精确状态。也不把缺页的页表处理写成操作系统课：入口仍是特权级那一套，只是流水线保证 EPC 可信。</p><p>后课默认：谈到异常，五级核是精确的；CPI 损失包含冲刷与陷阱路径，定量在下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多条指令在飞时，异常仍按程序序只报告一条。</li><li>提交点之前完成，之后冲刷；EPC 指向该指令。</li><li>乱序下的精确性靠后课 ROB。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V；Hennessy and Patterson, <em>CA:AQA</em> 异常与流水线。</li></ul>',9))])}const f=o(B,[["render",c]]);export{u as __pageData,f as default};
